"""Offline mutations of the retained fixture report; never run native helpers."""
import copy
import struct
import unittest

from devtools import terminal_oplock_verification as v


class OplockVerificationTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        # Prefer the eventual small committed source; the original local report
        # remains usable before closeout. Neither is generated by these tests.
        candidates = [v.ROOT/'analysis/terminal-oplock-controls-v2-20261112.json.gz',
                      v.ROOT/'.venv-audit/oplock-preflight-v2-20261112/report.json']
        cls.report, _ = v.read_source(next(p for p in candidates if p.exists()))

    def reject(self, change, message=None):
        report = copy.deepcopy(self.report)
        change(report)
        with self.assertRaisesRegex(ValueError, message or '.'):
            v.verify(report, check_disk=False)

    @staticmethod
    def edit_hex(obj, key, offset, value, fmt='<I'):
        data = bytearray.fromhex(obj[key])
        struct.pack_into(fmt, data, offset, value)
        obj[key] = data.hex()

    def test_real_source_has_only_fixture_qualification(self):
        proof = v.verify(self.report, check_disk=False)
        self.assertTrue(proof['fixture_capture_passed'])
        self.assertFalse(proof['accepted'])
        self.assertFalse(proof['original_game_adaptation_eligible'])
        self.assertFalse(proof['fault_cleanup_qualified'])
        self.assertFalse(proof['native_api_module_file_authenticated'])

    def test_missing_filename_and_old_v1_layout_rejected(self):
        self.reject(lambda r: r['cases'][1]['capture'].update(syscall_frames=[]), 'filename frame')
        old = v.ROOT/'.venv-audit/oplock-preflight-v1-20261112/report.json'
        if old.exists():
            report, _ = v.read_source(old)
            with self.assertRaisesRegex(ValueError, 'filename frame'):
                v.verify(report, check_disk=False)

    def test_tls_tail_teb_owner_and_slot_rejected(self):
        self.reject(lambda r: self.edit_hex(r['cases'][1]['capture'], 'payload_hex', 112, 0), 'entire 116')
        self.reject(lambda r: self.edit_hex(r['cases'][1]['capture'], 'TEB_hex', 36, 1), 'TEB owner')
        self.reject(lambda r: self.edit_hex(r['cases'][1]['capture'], 'slot_hex', 0, 0), 'live TLS slot')

    def test_context_and_descriptor_not_just_metadata(self):
        self.reject(lambda r: self.edit_hex(r['cases'][1]['capture'], 'context_after_hex', 176, 0xdeadbeef), 'unchanged WOW64')
        self.reject(lambda r: self.edit_hex(r['cases'][1]['capture'], 'descriptor_hex', 2, 0, '<H'), 'FS selector')

    def test_native_stack_stub_and_filename_binding(self):
        self.reject(lambda r: self.edit_hex(r['cases'][1]['capture'], 'stack_hex', 4+6*4, 7), 'arguments from original stack')
        self.reject(lambda r: self.edit_hex(r['cases'][1]['capture'], 'nt_create_code_hex', 12, 0, '<B'), 'syscall CALL')
        def change_name(r):
            frame = r['cases'][1]['capture']['syscall_frames'][0]
            self.edit_hex(frame, 'name_hex', len(bytes.fromhex(frame['name_hex']))-2, ord('x'), '<H')
        self.reject(change_name, 'exact locked payload')
        self.reject(lambda r: self.edit_hex(r['cases'][1]['capture']['syscall_frames'][0],
                                         'object_attributes_hex', 8, 1), 'pointer binding')

    def test_read_handle_is_not_rw_and_ack_required(self):
        self.reject(lambda r: self.edit_hex(r['cases'][1]['oplock'], 'output_hex', 4, 3), 'RW-to-R')
        self.reject(lambda r: self.edit_hex(r['cases'][1]['oplock'], 'output_hex', 12, 0), 'requiring ACK')
        self.reject(lambda r: r['cases'][1]['oplock'].update(watchdog_release=True), 'normal implicit')

    def test_clock_exit_and_original_debugger(self):
        self.reject(lambda r: r['cases'][1]['oplock'].update(release_begin_qpc=r['cases'][1]['capture']['captured_qpc']),
                    'held across live capture')
        self.reject(lambda r: r['cases'][1]['capture']['process'].update(debug_port=0), 'original debugger parent')
        self.reject(lambda r: r['cases'][1]['worker_exit'].update(code=259), 'retained worker exit0')
        self.reject(lambda r: r['cases'][0]['debugger']['events'][0].update(status=0), 'continuation policy')

    def test_cleanup_desktop_and_provenance_fail_closed(self):
        self.reject(lambda r: r['cases'][1]['owner'].update(job_empty=False), 'Job, parent')
        self.reject(lambda r: r['cases'][1]['oplock'].update(async_completed=False), 'async lifetime')
        self.reject(lambda r: r['desktop_after'][1]['input_desktop'].update(foreground_pid=1), 'identity restored')
        self.reject(lambda r: r['implementations'].pop(), 'implementation provenance')
        self.reject(lambda r: r['implementations'][0].update(sha256='0'*64), 'implementation provenance')


class OplockFaultVerificationTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        candidates = [v.ROOT/'analysis/terminal-oplock-faults-v1-20261112.json.gz',
                      v.ROOT/'.venv-audit/oplock-faults-v1-20261112/report.json']
        cls.report, _ = v.read_source(next(p for p in candidates if p.exists()))

    def reject(self, change, message):
        report = copy.deepcopy(self.report)
        change(report)
        with self.assertRaisesRegex(ValueError, message):
            v.verify_faults(report, check_disk=False)

    def test_actual_faults_are_named_prechecks_not_normal_exit(self):
        proof = v.verify_faults(self.report, check_disk=False)
        self.assertTrue(proof['fault_prechecks_passed'])
        self.assertFalse(proof['all_fault_paths_qualified'])
        self.assertTrue(proof['cases'][2]['forced_job_containment_verified'])
        self.assertTrue(proof['cases'][2]['failure_before_target_suspend'])
        self.assertFalse(proof['cases'][2]['normal_worker_exit_proved'])

    def test_watchdog_and_no_opener_cannot_invent_break(self):
        self.reject(lambda r: r['cases'][0]['oplock'].update(output_hex='00'*24), 'no fabricated')
        self.reject(lambda r: r['cases'][1]['oplock'].update(watchdog_release=False), 'release owner')
        self.reject(lambda r: r['cases'][1]['oplock'].update(async_completed=False), 'async/event cleanup')

    def test_forced_containment_cannot_be_upgraded_or_left_active(self):
        self.reject(lambda r: r['cases'][2]['result']['owner'].update(forced=False), 'forced Job containment')
        self.reject(lambda r: r['cases'][2]['result']['owner'].update(job_empty=False), 'forced Job containment')
        self.reject(lambda r: r['cases'][2]['result'].update(worker_exit={'code': 0, 'wait': 0}), 'must not invent')
        self.reject(lambda r: r['cases'][2]['result'].update(error='different failure'), 'exact pre-capture')

    def test_raw_fault_break_and_frozen_dependencies(self):
        self.reject(lambda r: OplockVerificationTests.edit_hex(r['cases'][2]['result']['oplock'],
                                                              'output_hex', 12, 0), 'ACK-required break')
        self.reject(lambda r: r['sources'].pop(), 'fault provenance')
        self.reject(lambda r: r['after'][1]['input_desktop'].update(input_submitted=True), 'without input')


if __name__ == '__main__':
    unittest.main()
